using System.Buffers.Binary;
using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Xml.Linq;
using Rotula.App.Views;

namespace Rotula.Tests;

/// <summary>
/// The brand icons are generated by tools/brand and committed. These tests check the committed files and the wiring that makes
/// the executables, the installer and the document type use them, so a regeneration or a project edit cannot silently lose an icon.
/// </summary>
public class BrandIconTests
{
    private static readonly int[] ExpectedSizes = [16, 20, 24, 32, 40, 48, 64, 96, 128, 256];
    private static readonly byte[] PngSignature = [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "Rotula.sln"))) dir = dir.Parent;
        return dir?.FullName ?? throw new InvalidOperationException("Rotula.sln not found above the test folder.");
    }

    private static string Repo(params string[] parts) => Path.Combine([RepoRoot(), .. parts]);

    public static TheoryData<string> IconFiles => new()
    {
        Path.Combine("src", "Rotula.App", "Assets", "rotula.ico"),
        Path.Combine("src", "Rotula.App", "Assets", "rotula-document.ico"),
        Path.Combine("src", "Rotula.Mcp", "Assets", "rotula-mcp.ico"),
    };

    [Theory]
    [MemberData(nameof(IconFiles))]
    public void IconFile_HasEverySize_AsPngCompressedEntries(string relative)
    {
        byte[] ico = File.ReadAllBytes(Repo(relative));

        Assert.Equal(0, BinaryPrimitives.ReadUInt16LittleEndian(ico.AsSpan(0)));  // reserved
        Assert.Equal(1, BinaryPrimitives.ReadUInt16LittleEndian(ico.AsSpan(2)));  // type: icon
        int count = BinaryPrimitives.ReadUInt16LittleEndian(ico.AsSpan(4));
        Assert.Equal(ExpectedSizes.Length, count);

        var sizes = new List<int>();
        for (int i = 0; i < count; i++)
        {
            int entry = 6 + 16 * i;
            int width = ico[entry] == 0 ? 256 : ico[entry];
            int height = ico[entry + 1] == 0 ? 256 : ico[entry + 1];
            Assert.Equal(width, height);
            Assert.Equal(32, BinaryPrimitives.ReadUInt16LittleEndian(ico.AsSpan(entry + 6)));  // bits per pixel
            int length = (int)BinaryPrimitives.ReadUInt32LittleEndian(ico.AsSpan(entry + 8));
            int offset = (int)BinaryPrimitives.ReadUInt32LittleEndian(ico.AsSpan(entry + 12));
            Assert.True(offset + length <= ico.Length, $"Entry {width} runs past the end of the file.");

            // The image data must be a PNG whose own header agrees with the directory entry.
            Assert.True(ico.AsSpan(offset, 8).SequenceEqual(PngSignature), $"Entry {width} is not PNG-compressed.");
            Assert.Equal(width, (int)BinaryPrimitives.ReadUInt32BigEndian(ico.AsSpan(offset + 16)));
            Assert.Equal(height, (int)BinaryPrimitives.ReadUInt32BigEndian(ico.AsSpan(offset + 20)));
            sizes.Add(width);
        }
        Assert.Equal(ExpectedSizes, sizes);
    }

    [Fact]
    public void Projects_ReferenceTheirIcon_AndTheFilesExist()
    {
        string app = (string?)XDocument.Load(Repo("src", "Rotula.App", "Rotula.App.csproj")).Descendants("ApplicationIcon").Single() ?? "";
        string mcp = (string?)XDocument.Load(Repo("src", "Rotula.Mcp", "Rotula.Mcp.csproj")).Descendants("ApplicationIcon").Single() ?? "";
        Assert.Equal("Assets/rotula.ico", app.Replace('\\', '/'));
        Assert.Equal("Assets/rotula-mcp.ico", mcp.Replace('\\', '/'));
        Assert.True(File.Exists(Repo("src", "Rotula.App", app)));
        Assert.True(File.Exists(Repo("src", "Rotula.Mcp", mcp)));

        // Windows show the same file through Window.Icon, so it must also ship inside the app as a WPF resource.
        var resources = XDocument.Load(Repo("src", "Rotula.App", "Rotula.App.csproj")).Descendants("Resource").Select(e => (string?)e.Attribute("Include")?.Value.Replace('\\', '/'));
        Assert.Contains("Assets/rotula.ico", resources);
    }

    [Fact]
    public void Installer_UsesTheBrandFiles_AndStagesTheDocumentIcon()
    {
        string iss = File.ReadAllText(Repo("packaging", "installer", "Rotula.iss"));
        Assert.Contains(@"SetupIconFile=..\..\src\Rotula.App\Assets\rotula.ico", iss);
        Assert.Contains("WizardImageFile=", iss);
        Assert.Contains("WizardSmallImageFile=", iss);
        Assert.Contains(@"ValueData: ""{app}\Assets\rotula-document.ico""", iss);
        Assert.Contains(@"Source: ""{#SourceDir}\Assets\rotula-document.ico""", iss);

        // Every image the script lists must exist and be a 24-bit BMP of the size in its name.
        foreach (string key in new[] { "WizardImageFile", "WizardSmallImageFile" })
        {
            string line = iss.Split('\n').Single(l => l.StartsWith(key + "=", StringComparison.Ordinal)).Trim();
            foreach (string file in line[(key.Length + 1)..].Split(','))
            {
                byte[] bmp = File.ReadAllBytes(Repo("packaging", "installer", file.Replace('\\', Path.DirectorySeparatorChar)));
                Assert.Equal((byte)'B', bmp[0]);
                Assert.Equal((byte)'M', bmp[1]);
                Assert.Equal(24, BinaryPrimitives.ReadUInt16LittleEndian(bmp.AsSpan(28)));
                string size = Path.GetFileNameWithoutExtension(file).Split('-').Last();
                Assert.Equal(size, $"{BinaryPrimitives.ReadInt32LittleEndian(bmp.AsSpan(18))}x{BinaryPrimitives.ReadInt32LittleEndian(bmp.AsSpan(22))}");
            }
        }

        Assert.Contains(@"'src\Rotula.App\Assets\rotula-document.ico'", File.ReadAllText(Repo("packaging", "installer", "build-installer.ps1")));
    }

    [Fact]
    public void BuiltApplication_CarriesTheIconWithAllSizes()
    {
        // The test project references the WPF app, so its apphost (Rotula.App.exe) sits next to Rotula.App.dll.
        string exe = Path.ChangeExtension(typeof(Rotula.App.Views.BrandIcon).Assembly.Location, ".exe");
        if (!File.Exists(exe)) return;  // no apphost in this build layout; the csproj test above still guards the setting

        IntPtr module = LoadLibraryEx(exe, IntPtr.Zero, LoadLibraryAsDatafile);
        Assert.NotEqual(IntPtr.Zero, module);
        try
        {
            int groups = 0, images = -1;
            EnumResourceNames(module, (IntPtr)14, (_, _, name, _) =>
            {
                groups++;
                IntPtr info = FindResource(module, name, (IntPtr)14);
                IntPtr data = LoadResource(module, info);
                images = Marshal.ReadInt16(LockResource(data), 4);  // GRPICONDIR.idCount
                return true;
            }, IntPtr.Zero);
            Assert.Equal(1, groups);
            Assert.Equal(ExpectedSizes.Length, images);
        }
        finally
        {
            FreeLibrary(module);
        }
    }

    [Fact]
    public void BrandIcon_DecodesTheEmbeddedIco_WithEveryFrame()
    {
        int frames = WpfTestHost.Run(() =>
        {
            var frame = Assert.IsAssignableFrom<BitmapFrame>(BrandIcon.Source);
            Assert.IsType<IconBitmapDecoder>(frame.Decoder);
            return frame.Decoder.Frames.Count;
        });
        Assert.Equal(ExpectedSizes.Length, frames);
    }

    [Fact]
    public void Windows_ShowTheIcon_AndTheBrandImagesResolve()
    {
        WpfTestHost.Run(() =>
        {
            // A dialog gets its icon from the base class constructor, so this also covers every other secondary window.
            var about = new AboutWindow();
            Assert.NotNull(about.Icon);
            foreach (string key in new[] { "BrandMark", "BrandMark24", "BrandMark20" })
                Assert.IsType<DrawingImage>(Application.Current.TryFindResource(key));
            return 0;
        });
    }

    private const uint LoadLibraryAsDatafile = 0x00000002;

    private delegate bool EnumResNameProc(IntPtr module, IntPtr type, IntPtr name, IntPtr param);

    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    private static extern IntPtr LoadLibraryEx(string fileName, IntPtr file, uint flags);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool FreeLibrary(IntPtr module);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool EnumResourceNames(IntPtr module, IntPtr type, EnumResNameProc callback, IntPtr param);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr FindResource(IntPtr module, IntPtr name, IntPtr type);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr LoadResource(IntPtr module, IntPtr info);

    [DllImport("kernel32.dll")]
    private static extern IntPtr LockResource(IntPtr data);
}
